:root { --bg: #F4F5F7; --surface: #FFFFFF; --surface-2: #F0F2F5; --surface-3: #E8EBEF; --ink: #181818; --ink-2: #4D5664; --ink-3: #8E96A2; --ink-4: #C5CBD3; --yellow: #FFDD2D; --yellow-d: #F3CE17; --yellow-soft: #FFF6C2; --green: #26B36E; --green-soft: #DEF5E8; --red: #F52E2E; --red-soft: #FCE2E2; --blue-soft: #E1ECFE; --blue: #428BF9; --shadow-sm: 0 1px 2px rgba(20, 22, 28, 0.04); --shadow: 0 2px 8px rgba(20, 22, 28, 0.05), 0 12px 28px rgba(20, 22, 28, 0.04); --radius: 20px; --radius-sm: 14px; --sans: 'Onest', system-ui, -apple-system, sans-serif; --mono: 'JetBrains Mono', ui-monospace, monospace; --ease: cubic-bezier(0.2, 0.7, 0.2, 1); }*, ::before, ::after { box-sizing: border-box; }html, body { margin: 0px; padding: 0px; background: var(--bg); color: var(--ink); font-family: var(--sans); font-feature-settings: "ss01", "ss03", "tnum"; -webkit-font-smoothing: antialiased; text-rendering: optimizelegibility; letter-spacing: -0.005em; min-height: 100vh; }button { font-family: inherit; cursor: pointer; }a { color: inherit; }.shell { max-width: 760px; margin: 0px auto; padding: 16px 14px 80px; }@media (min-width: 720px) {
  .shell { padding: 28px 28px 80px; max-width: 1080px; }
}.topbar { display: flex; align-items: center; gap: 12px; margin-bottom: 22px; }.brand { display: flex; align-items: center; gap: 10px; }.brand__mark { width: 36px; height: 36px; border-radius: 12px; background: var(--yellow); display: grid; place-items: center; box-shadow: rgba(243, 206, 23, 0.4) 0px 2px 6px; }.brand__mark::after { content: ""; width: 12px; height: 12px; border-radius: 50%; background: var(--ink); }.brand__name { font-weight: 700; font-size: 17px; letter-spacing: -0.02em; line-height: 1; }.brand__sub { font-size: 12px; color: var(--ink-3); margin-top: 2px; line-height: 1; font-weight: 400; }.intro { margin-bottom: 20px; }.intro__title { font-size: clamp(28px, 5vw, 40px); font-weight: 700; letter-spacing: -0.03em; line-height: 1.1; margin: 0px 0px 10px; }.intro__lede { font-size: 15px; color: var(--ink-2); margin: 0px; line-height: 1.5; max-width: 60ch; }.status { display: flex; align-items: center; gap: 12px; padding: 14px 16px; background: var(--surface); border-radius: var(--radius-sm); box-shadow: var(--shadow-sm); margin-bottom: 16px; transition: background 0.3s var(--ease); }.status.live { background: rgb(24, 24, 24); color: rgb(255, 255, 255); }.status__dot { width: 10px; height: 10px; border-radius: 50%; background: var(--ink-4); flex-shrink: 0; }.status.live .status__dot { background: var(--red); box-shadow: rgba(245, 46, 46, 0.22) 0px 0px 0px 4px; animation: 1.5s ease-in-out 0s infinite normal none running pulse; }@keyframes pulse { 
  0%, 100% { box-shadow: rgba(245, 46, 46, 0.22) 0px 0px 0px 4px; }
  50% { box-shadow: rgba(245, 46, 46, 0.04) 0px 0px 0px 8px; }
}.status__label { font-size: 13px; color: var(--ink-3); font-weight: 500; }.status.live .status__label { color: rgba(255, 255, 255, 0.55); }.status__value { margin-left: auto; font-weight: 600; font-size: 14px; }.grid { display: grid; grid-template-columns: 1fr; gap: 12px; }@media (min-width: 880px) {
  .grid--2 { grid-template-columns: 1fr 1fr; }
  .grid--3 { grid-template-columns: repeat(3, 1fr); }
}.card { background: var(--surface); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow-sm); }@media (min-width: 720px) {
  .card { padding: 24px; }
}.card__head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; margin-bottom: 16px; }.card__title { font-size: 18px; font-weight: 700; letter-spacing: -0.02em; margin: 0px; line-height: 1.2; }.card__hint { font-size: 13px; color: var(--ink-3); margin: 4px 0px 0px; line-height: 1.4; }.card__badge { flex-shrink: 0; font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 99px; background: var(--surface-2); color: var(--ink-2); }.card__badge--yellow { background: var(--yellow-soft); color: rgb(110, 88, 0); }.card__badge--blue { background: var(--blue-soft); color: rgb(28, 91, 194); }.field { display: block; margin-bottom: 10px; }.field:last-of-type { margin-bottom: 0px; }.field__label { display: block; font-size: 13px; color: var(--ink-3); margin-bottom: 6px; font-weight: 500; }.field__input { width: 100%; padding: 14px 16px; background: var(--surface-2); border: 2px solid transparent; border-radius: 14px; font-family: inherit; font-size: 15px; font-weight: 500; color: var(--ink); transition: background 0.2s var(--ease), border-color 0.2s var(--ease); appearance: none; }.field__input::placeholder { color: var(--ink-3); font-weight: 400; }.field__input:focus { outline: none; background: var(--surface); border-color: var(--ink); }.select-wrap { position: relative; }.select-wrap::after { content: ""; position: absolute; right: 18px; top: 50%; width: 8px; height: 8px; border-right: 2px solid var(--ink-2); border-bottom: 2px solid var(--ink-2); transform: translateY(-70%) rotate(45deg); pointer-events: none; }.field__input--select { padding-right: 40px; cursor: pointer; }.btns { display: flex; gap: 8px; margin-top: 14px; }.btn { flex: 1 1 0%; padding: 14px 20px; border-width: medium; border-style: none; border-color: currentcolor; border-image: initial; border-radius: 14px; font-family: inherit; font-size: 15px; font-weight: 600; cursor: pointer; transition: transform 0.15s var(--ease), background 0.2s var(--ease), box-shadow 0.2s var(--ease); }.btn--primary { background: var(--yellow); color: var(--ink); box-shadow: rgba(243, 206, 23, 0.3) 0px 1px 2px; }.btn--primary:hover { background: var(--yellow-d); box-shadow: rgba(243, 206, 23, 0.35) 0px 4px 12px; }.btn--primary:active { transform: scale(0.97); }.btn--ghost { background: var(--surface-2); color: var(--ink); }.btn--ghost:hover { background: var(--surface-3); }.btn--ghost:active { transform: scale(0.97); }.btn[disabled] { opacity: 0.55; cursor: progress; pointer-events: none; }.btn .spinner { display: inline-block; width: 14px; height: 14px; border-width: 2px; border-style: solid; border-color: currentcolor transparent currentcolor currentcolor; border-image: initial; border-radius: 50%; margin-right: 8px; vertical-align: -3px; animation: 0.7s linear 0s infinite normal none running spin; }@keyframes spin { 
  100% { transform: rotate(360deg); }
}.form-error { margin-top: 10px; padding: 10px 12px; background: var(--red-soft); border-radius: 10px; font-size: 13px; color: rgb(181, 21, 26); font-weight: 500; display: none; animation: shake 0.4s var(--ease); }.form-error.show { display: block; }@keyframes shake { 
  0%, 100% { transform: translateX(0px); }
  25% { transform: translateX(-4px); }
  75% { transform: translateX(4px); }
}.hint { display: flex; align-items: flex-start; gap: 10px; padding: 12px 14px; background: var(--yellow-soft); border-radius: 12px; font-size: 13px; line-height: 1.5; color: rgb(110, 88, 0); margin-top: 14px; }.hint__icon { flex-shrink: 0; width: 20px; height: 20px; border-radius: 50%; background: var(--yellow); color: var(--ink); display: grid; place-items: center; font-weight: 700; font-size: 12px; }.hint code { font-family: var(--mono); font-size: 12px; padding: 1px 5px; background: rgba(110, 88, 0, 0.1); border-radius: 4px; font-weight: 500; }.zone { padding: 18px; border-radius: 16px; }.zone--mask { background: var(--red-soft); }.zone--block { background: var(--yellow-soft); }.zone--clear { background: var(--green-soft); }.zone__top { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 12px; }.zone__icon { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; font-size: 18px; font-weight: 700; }.zone--mask .zone__icon { background: var(--red); color: rgb(255, 255, 255); }.zone--block .zone__icon { background: var(--yellow); color: var(--ink); }.zone--clear .zone__icon { background: var(--green); color: rgb(255, 255, 255); }.zone__chip { font-family: var(--mono); font-size: 11px; font-weight: 500; padding: 4px 8px; border-radius: 6px; background: rgba(255, 255, 255, 0.6); color: var(--ink-2); }.zone__title { font-size: 16px; font-weight: 700; letter-spacing: -0.02em; margin: 0px 0px 4px; }.zone__copy { font-size: 13px; color: var(--ink-2); margin: 0px 0px 12px; line-height: 1.4; }.zone__sample { padding: 10px 12px; background: rgba(255, 255, 255, 0.6); border-radius: 10px; font-family: var(--mono); font-size: 12px; color: var(--ink); font-weight: 500; min-height: 38px; display: flex; align-items: center; }.zone--mask .zone__sample.rec-mask { color: var(--red); }.log { max-height: 320px; overflow-y: auto; margin: 0px -4px; padding: 0px 4px; }.log__row { display: flex; align-items: center; gap: 12px; padding: 12px 0px; border-bottom: 1px solid var(--surface-3); animation: slide-in 0.35s var(--ease) both; }.log__row:last-child { border-bottom: 0px; }@keyframes slide-in { 
  0% { opacity: 0; transform: translateX(-6px); }
  100% { opacity: 1; transform: none; }
}.log__icon { flex-shrink: 0; width: 36px; height: 36px; border-radius: 12px; display: grid; place-items: center; background: var(--surface-2); color: var(--ink-2); font-weight: 700; font-size: 14px; }.log__row.evt-search .log__icon { background: var(--blue-soft); color: var(--blue); }.log__row.evt-filter .log__icon { background: var(--yellow-soft); color: rgb(110, 88, 0); }.log__row.evt-manual .log__icon { background: var(--red-soft); color: var(--red); }.log__main { flex: 1 1 0%; min-width: 0px; }.log__name { font-weight: 500; font-size: 14px; color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.log__sub { font-size: 12px; color: var(--ink-3); margin-top: 2px; font-family: var(--mono); font-weight: 400; }.log__empty { padding: 28px 0px; text-align: center; color: var(--ink-3); font-size: 14px; }.reveal { opacity: 0; transform: translateY(8px); animation: reveal 0.5s var(--ease) forwards; }@keyframes reveal { 
  100% { opacity: 1; transform: none; }
}.r-1 { animation-delay: 0.02s; }.r-2 { animation-delay: 0.08s; }.r-3 { animation-delay: 0.14s; }.r-4 { animation-delay: 0.2s; }.r-5 { animation-delay: 0.26s; }@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { animation: auto ease 0s 1 normal none running none !important; transition: none !important; }
}
